/* Une large carte des possibles et un chemin explicite vers chaque métier. */
let careerSection='jobs';let careerFilter={q:'',domain:'all',access:'all',page:0};
const rankNames=['Entrée / exécution','Métier qualifié','Confirmé·e / spécialiste','Responsabilité','Direction / forte reconnaissance','Fonction exceptionnelle'];
const contractNames={stable:'Stable',temporary:'Temporaire / précaire',freelance:'Indépendant / variable',mandate:'Mandat public'};
function careerTabs(){return`<div class="filter career-sections">${[['jobs','Métiers & parcours'],['public','Pouvoir & citoyenneté'],['social','Précarité & réseaux']].map(([id,t])=>`<button class="${careerSection===id?'active':''}" onclick="careerSection='${id}';render()">${t}</button>`).join('')}</div>`}
function aspirationCard(){const p=state.person,j=Life.jobById(p.occupationGoal);if(!j)return`<div class="card"><h3>Un cap, sans destin imposé.</h3><p>Choisissez un métier dans le catalogue pour suivre les étapes qui vous en séparent. Vous pouvez changer d’aspiration : le diplôme, les années d’expérience et les liens déjà construits ne disparaissent pas.</p><button class="btn" onclick="occupationAtlas()">Explorer les ${Life.occupations.length} métiers ↗</button></div>`;const req=Life.jobReasons(state,j);return`<div class="card aspiration"><div class="eyebrow">Votre aspiration</div><h3 style="margin-top:10px">${esc(j.title)}</h3>${req.length?`<p>${req.length} condition${req.length>1?'s':''} reste${req.length>1?'nt':''} à remplir pour cette voie.</p><ul class="requirements">${req.slice(0,4).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="positive">Vous remplissez les conditions d’entrée de cette voie. Une candidature reste incertaine.</p>'}<button class="btn" onclick="occupationDetail('${j.id}')">Voir les étapes et les options ↗</button></div>`}
careerView=function(){Life.ensure(state);const p=state.person;if(careerSection==='public')return heading('Le pouvoir se construit. Il peut se perdre.','L’éligibilité, l’expérience politique et l’issue d’une campagne sont trois choses différentes.')+careerTabs()+publicLifeView();if(careerSection==='social')return heading('Toutes les vies ne commencent pas avec les mêmes portes.','La précarité et l’entrée dans un réseau sont des trajectoires, pas une valeur donnée à une personne.')+careerTabs()+socialLifeView();return`${heading('410 métiers. Beaucoup de façons de vivre.','41 domaines, des contrats précaires aux fonctions les plus rares.',`<button class="pill" onclick="occupationAtlas()">Le catalogue complet ↗</button>`)}${careerTabs()}<div class="grid"><div class="card"><div class="eyebrow">Votre situation professionnelle</div><h3>${esc(p.job)}</h3><div class="big-number">${money(p.salary)} <small>/ an</small></div>${micro('Qualification générale',['Sans qualification professionnelle','Professionnelle','Supérieure','Spécialisée / doctorale'][p.education]||'Supérieure')}${micro('Contrat',contractNames[p.career?.contract]||'Sans contrat salarié')}${micro('Dans ce poste',(p.career?.years||0)+' ans')}${micro('Dans ce domaine',(p.experience[p.career?.sector]||0)+' ans')}${micro('Qualifications spécifiques',Object.keys(p.credentials).length)}${p.career?`<div class="row"><button class="btn primary" onclick="act('promotion')" ${!Life.availablePromotion(state)||!p.points?'disabled':''}>Progresser vers un autre poste</button><button class="btn" onclick="careerRhythm()">Rythme de travail</button><button class="btn danger" onclick="confirmQuit()">Quitter ce poste</button></div><p class="hint">Une progression ne remplace jamais une qualification obligatoire : on ne passe pas d’un poste d’aide aux soins à la chirurgie par simple promotion.</p>`:'<p>Le marché n’offre pas les mêmes possibilités à chaque année. Le catalogue permet aussi de préparer un métier qui n’est pas encore accessible.</p>'}${p.age>=60&&!p.retired?'<button class="btn" onclick="act(\'retire\')">Prendre ma retraite</button>':''}</div><div class="card"><h3>Vos appuis et votre reconnaissance</h3>${skillBars(p)}${micro('Réseau',Math.round(p.network)+'/100')}${micro('Réputation',Math.round(p.reputation)+'/100')}${micro('Reconnaissance créative',Math.round(p.visibility.creative)+'/100')}${micro('Reconnaissance scientifique',Math.round(p.visibility.science)+'/100')}${micro('Reconnaissance sportive',Math.round(p.visibility.sport)+'/100')}<div class="row"><button class="btn" onclick="act('prepare')">Préparer · 1</button><button class="btn" onclick="act('network')">Réseau · 1</button><button class="btn" onclick="act('careerImpact')">Réalisation marquante · D20</button></div></div></div><div class="grid" style="margin-top:18px">${aspirationCard()}<div class="card"><h3>Un vrai parcours de qualification</h3><p>Le diplôme général ouvre certaines portes. La médecine, le pilotage, la justice, la diplomatie ou la conduite professionnelle exigent en plus leur propre parcours. Une migration peut demander une reconnaissance locale.</p><button class="btn" onclick="credentialSchool()">Formations & reconnaissances ↗</button><button class="btn" onclick="launchProject('degree')">Préparer des études supérieures</button></div></div><div class="section-head" style="margin-top:30px"><h3>Les offres de cette année</h3><span class="pill">${phaseLabels[state.world.phase]}</span></div><div class="grid">${Life.offers(state).map(offerCard).join('')||'<div class="card"><p>Aucune offre ne correspond à vos conditions actuelles. Une formation, un autre pays ou une activité temporaire peuvent changer la suite.</p></div>'}</div><div class="card" style="margin-top:20px"><h3>Un monde professionnel bien plus large</h3><div class="domain-chips">${Object.values(Life.domains).map(d=>`<button onclick="occupationAtlas('${d.id}')">${esc(d.name)} <small>10</small></button>`).join('')}</div></div>${p.careerHistory.length?`<div class="card"><h3>Vos chapitres professionnels</h3>${p.careerHistory.slice(-8).reverse().map(x=>micro(x.since+'–'+x.until,esc(x.title))).join('')}</div>`:''}`};
function offerCard(o){const p=state.person,j=Life.jobById(o.jobId),m=Life.checkModel(state,'job',o),reason=Life.jobReasons(state,j)[0]||p.actions['occupation-'+j.id]?'':'';return`<article class="card"><div class="eyebrow">${esc(Life.domains[o.sector].name)}</div><h3 style="margin-top:12px">${esc(o.title)}</h3><div class="big-number">${money(o.salary)} <small>/ an</small></div>${micro('Contrat',contractNames[o.contract])}${micro('Responsabilité',rankNames[j.rank])}${micro('Chance du modèle',percent(m.probability))}<div class="row"><button class="btn primary" onclick="act('applyJob','${o.id}')" ${p.actions['occupation-'+j.id]||!p.points||!p.alive?'disabled':''}>Candidater · D20</button><button class="btn" onclick="occupationDetail('${j.id}')">Voir le parcours</button></div></article>`}
function atlasControls(){return`<div class="atlas-controls"><input id="occupation-search" aria-label="Rechercher un métier" placeholder="Chirurgie, usine, diplomatie, IA, train…" value="${esc(careerFilter.q)}" oninput="updateOccupationFilter('q',this.value)"><select aria-label="Domaine du métier" onchange="updateOccupationFilter('domain',this.value)"><option value="all">Tous les domaines · 410 métiers</option>${Object.values(Life.domains).map(d=>`<option value="${d.id}" ${careerFilter.domain===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select><select aria-label="Conditions d’accès" onchange="updateOccupationFilter('access',this.value)">${[['all','Toutes les possibilités'],['ready','Accessibles maintenant'],['future','À préparer'],['rare','Fonctions rares']].map(([v,t])=>`<option value="${v}" ${careerFilter.access===v?'selected':''}>${t}</option>`).join('')}</select></div>`}
function occupationAtlas(domain='all'){pauseClock();careerFilter={q:'',domain,access:'all',page:0};modal(`<h2>La carte des métiers.</h2><p>410 professions dans 41 domaines. Les revenus affichés sont des montants annuels de jeu dans votre pays actuel, pas des salaires observés.</p>${atlasControls()}<div id="occupation-results">${occupationResults()}</div><div class="hint">Catalogue original couvrant les grands groupes ISCO-08 de l’OIT ; catégories et conditions adaptées au jeu.</div>`);$('#modal').classList.add('wide-modal')}
function normalizeSearch(t){return t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function occupationResults(){const text=normalizeSearch(careerFilter.q),filtered=Life.occupations.filter(j=>{const reasons=Life.jobReasons(state,j);return(careerFilter.domain==='all'||j.sector===careerFilter.domain)&&(!text||normalizeSearch(j.title+' '+Life.domains[j.sector].name).includes(text))&&(careerFilter.access==='ready'?!reasons.length:careerFilter.access==='future'?reasons.length:careerFilter.access==='rare'?j.rank>=4:true)}),limit=20,totalPages=Math.ceil(filtered.length/limit),page=Math.min(careerFilter.page,Math.max(0,totalPages-1));careerFilter.page=page;return`<div class="section-head" style="margin:18px 0"><span class="history-total">${filtered.length} métiers · page ${page+1}/${Math.max(1,totalPages)}</span><span class="history-total">Votre pays : ${esc(Life.country(state).name)}</span></div><div class="occupation-list">${filtered.slice(page*limit,(page+1)*limit).map(j=>{const reasons=Life.jobReasons(state,j);return`<button class="occupation-row" onclick="occupationDetail('${j.id}')"><span><strong>${esc(j.title)}</strong><small>${esc(Life.domains[j.sector].name)} · ${rankNames[j.rank]}</small></span><span><b>${money(Life.makeOffer(state,j).salary)}</b><small class="${reasons.length?'':'positive'}">${j.path?'Parcours politique':reasons.length?reasons.length+' condition(s) à préparer':'Conditions remplies'} ↗</small></span></button>`}).join('')||'<p>Aucun métier ne correspond à ces filtres.</p>'}</div><div class="row" style="margin-top:16px"><button class="btn" ${page<=0?'disabled':''} onclick="occupationPage(-1)">← Précédents</button><button class="btn" ${page>=totalPages-1?'disabled':''} onclick="occupationPage(1)">Suivants →</button></div>`}
function updateOccupationFilter(key,value){careerFilter[key]=value;careerFilter.page=0;const node=document.getElementById('occupation-results');if(node)node.innerHTML=occupationResults()}
function occupationPage(delta){careerFilter.page+=delta;const node=document.getElementById('occupation-results');if(node){node.innerHTML=occupationResults();node.scrollTop=0}}
function politicalOfficeForJob(j){return j.rank>=4?'head':j.rank>=3?'minister':j.rank>=2?'national':j.title==='Maire'?'mayor':'local'}
function occupationDetail(id){const j=Life.jobById(id);if(!j)return;pauseClock();const p=state.person,reasons=Life.jobReasons(state,j),offer=Life.makeOffer(state,j,true),m=Life.checkModel(state,'job',offer);modal(`<div class="eyebrow">${esc(Life.domains[j.sector].name)}</div><h2 style="margin-top:12px">${esc(j.title)}</h2>${micro('Rémunération annuelle de référence',money(offer.salary))}${micro('Contrat',contractNames[j.contract])}${micro('Palier',rankNames[j.rank])}${micro('Années dans ce domaine requises',j.minExperience)}${micro('Compétence principale',Life.skills[Life.domains[j.sector].skill]+' · '+j.minSkill+'/100 requis')}<div class="requirements-box"><h3>${reasons.length?'Ce qui vous en sépare':'Les conditions sont remplies'}</h3>${reasons.length?`<ul class="requirements">${reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>Vous pouvez candidater. L’accès au métier reste soumis à la sélection et à la concurrence.</p>'}</div><div class="row"><button class="btn" onclick="act('setOccupationGoal','${j.id}');occupationDetail('${j.id}')">En faire mon aspiration</button>${j.path?`<button class="btn primary" onclick="publicLifeModal()">Préparer le parcours politique →</button>`:`<button class="btn primary" ${reasons.length||!p.points?'disabled':''} onclick="document.getElementById('modal').close();act('applyOccupation','${j.id}')">Candidature spontanée · ${percent(m.probability)}</button>`}${j.license?`<button class="btn" onclick="credentialDetail('${j.license}')">Préparer la qualification ↗</button>`:''}${p.education<j.degree?`<button class="btn" onclick="launchProject('degree')">Commencer par les études</button>`:''}</div><p class="hint">Une candidature spontanée est plus difficile qu’une offre ouverte. Un jet critique n’annule jamais les diplômes, licences, conditions de citoyenneté ou années d’expérience nécessaires.</p>`)}
function credentialSchool(){pauseClock();const p=state.person;modal(`<h2>Des qualifications qui ouvrent des portes.</h2><p>Les licences ne se transmettent pas aux enfants. Une qualification réglementée peut aussi demander une reconnaissance après une migration.</p><div class="occupation-list">${Object.entries(Life.certifications).map(([id,c])=>`<button class="occupation-row" onclick="credentialDetail('${id}')"><span><strong>${esc(c.name)}</strong><small>${c.work} unités de formation · examen D20 · ${money(Life.reference(state)*c.cost)} / année active</small></span><span class="${Life.certificateValid(p,id)?'positive':''}">${Life.certificateValid(p,id)?'Reconnue':p.credentials[id]?'Reconnaissance locale':'À préparer'} ↗</span></button>`).join('')}</div>`);$('#modal').classList.add('wide-modal')}
function credentialDetail(id){const c=Life.certifications[id],p=state.person,recognized=Life.certificateValid(p,id),existing=!!p.credentials[id];modal(`<h2>${esc(c.name)}</h2>${micro('Formation complète',c.work+' unités de travail')}${micro('Budget annuel de référence',money(Life.reference(state)*c.cost))}${micro('Compétence de l’examen',Life.skills[c.skill])}${micro('Diplôme préalable',['Aucun','Professionnel','Supérieur','Spécialisé'][c.edu])}${c.requires?micro('Qualification préalable',Life.certifications[c.requires].name):''}${existing?micro('Déjà reconnue en',p.credentials[id].countries.map(code=>Life.countries.find(c=>c.code===code)?.name||code).join(', ')):''}<p>${recognized?'Cette qualification est déjà reconnue dans votre pays.':existing?'Vous avez la qualification, mais devez faire reconnaître votre parcours localement.':'Une formation prend du temps, demande un financement et se termine par un examen. L’expérience et les compétences acquises avant cet examen comptent.'}</p><div class="row"><button class="btn primary" ${recognized||p.age<18?'disabled':''} onclick="const r=Life.action(state,'${existing?'recognizeCredential':'trainCredential'}','${id}');if(r.ok){save();document.getElementById('modal').close();render()}toast(r.message)">${existing?'Préparer la reconnaissance':'Engager cette formation'}</button>${p.education<c.edu?`<button class="btn" onclick="launchProject('degree')">Préparer d’abord un diplôme</button>`:''}</div><p class="hint">Les durées et autorisations sont simplifiées pour le jeu ; elles ne décrivent pas les démarches officielles du pays.</p>`)}
function publicLifeView(){const p=state.person,pol=p.politics;return`<div class="grid"><div class="card"><h3>Votre place dans la vie publique</h3>${micro('Mandat actuel',esc(pol.office?.title||'Aucun'))}${micro('Expérience civique',pol.experience.toFixed(1)+' ans')}${micro('Soutien local',Math.round(pol.local)+'/100')}${micro('Confiance publique',Math.round(pol.trust)+'/100')}${micro('Notoriété nationale',Math.round(pol.profile)+'/100')}${micro('Soutien d’une organisation',Math.round(pol.party)+'/100')}<div class="row"><button class="btn" onclick="act('civicEngage')">M’engager localement · 1</button><button class="btn" onclick="act('partyWork')">Construire des soutiens · 1</button><button class="btn" onclick="act('servePublic')">Honorer un engagement · 1</button></div><p class="hint">Les engagements réguliers comptent davantage qu’une candidature isolée. Ces actions ne se répètent pas à l’infini dans la même année.</p></div><div class="card"><h3>Ce que votre histoire permet déjà</h3>${citizenshipPanel()}<div class="row"><button class="btn" onclick="act('residency')">Stabiliser mon séjour · D20</button><button class="btn" onclick="act('naturalize')">Demander la citoyenneté · D20</button><button class="btn" onclick="launchProject('migration')">Préparer une migration</button></div><p class="hint">Les étapes de séjour et de naturalisation sont des règles de jeu simplifiées. Une naturalisation change votre citoyenneté actuelle, jamais celle que vous aviez à la naissance.</p></div></div><div class="section-head" style="margin-top:26px"><h3>Les marches vers des responsabilités plus hautes</h3></div><div class="grid">${Object.entries(Life.officeTypes).map(([key,t])=>{const reasons=Life.officeConditions(state,key),formal=Life.officeConditions(state,key,p,true);return`<div class="card"><div class="eyebrow">${key==='head'?'Une trajectoire exceptionnelle':'Parcours politique'}</div><h3 style="margin-top:12px">${esc(Life.officeTitle(state,key))}</h3>${micro('Âge minimum du modèle',t.minAge+' ans')}${micro('Expérience civique',t.exp+' ans')}${micro('Réserve de campagne',money(Life.reference(state)*t.deposit))}<div class="qualification-status ${formal.length?'blocked':'ready'}">${formal.length?formal.map(x=>esc(x)).join('<br>'):'Conditions d’éligibilité formelle remplies dans le modèle.'}</div>${reasons.length?`<ul class="requirements">${reasons.filter(x=>!formal.includes(x)).slice(0,6).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="positive">Votre parcours permet de préparer cette campagne.</p>'}<button class="btn primary" ${reasons.length?'disabled':''} onclick="startOfficeCampaign('${key}')">Construire cette campagne →</button></div>`}).join('')}</div><div class="notice">Pour la présidence américaine, le moteur exige la citoyenneté américaine dès la naissance, 35 ans et 14 années de résidence cumulée aux États-Unis. Les autres pays et fonctions suivent des règles institutionnelles simplifiées, signalées comme telles. Un D20 ne peut contourner une condition formelle.</div>`}
function citizenshipPanel(){const p=state.person,n=c=>Life.countries.find(x=>x.code===c)?.name||c;return`${micro('Pays de naissance',esc(n(p.bornCountry)))}${micro('Citoyennetés actuelles',p.nationalities.map(n).map(esc).join(', '))}${micro('Citoyennetés à la naissance',p.citizensAtBirth.map(n).map(esc).join(', '))}${micro('Résidence dans le pays actuel',(p.residency[p.country]||0)+' ans')}${micro('Résidence cumulée aux États-Unis',(p.residency.US||0)+' ans')}${micro('Citoyenneté américaine de naissance',p.usCitizenAtBirth?'Oui':'Non')}`}
function startOfficeCampaign(key){const reasons=Life.officeConditions(state,key);if(reasons.length){toast(reasons[0]);return}const t=Life.officeTypes[key];modal(`<h2>Une campagne pour ${esc(Life.officeTitle(state,key).toLowerCase())}.</h2><p>La préparation prendra ${t.work} unités de travail. Une réserve initiale de ${money(Life.reference(state)*t.deposit)} sera engagée, puis des frais de ${money(Life.reference(state)*t.cost)} pour chaque année active. Les dépenses restent perdues en cas de défaite.</p><p>Le résultat dépendra du soutien, de la confiance, de votre expérience et du contexte au moment de l’élection. Les conditions formelles seront vérifiées de nouveau.</p><button class="btn primary" onclick="const r=Life.action(state,'startCampaign','${key}');if(r.ok){save();document.getElementById('modal').close();render()}toast(r.message)">Engager cette campagne →</button>`)}
function publicLifeModal(){pauseClock();modal(`<h2>Les trajectoires publiques.</h2>${publicLifeView()}`);$('#modal').classList.add('wide-modal')}
function socialLifeView(){const p=state.person,g=p.outlaw;return`<div class="grid"><div class="card"><h3>Votre stabilité actuelle</h3>${micro('Logement',({stable:'Stable',fragile:'Fragilisé',street:'Sans logement stable'})[p.social.housing])}${micro('Années de difficultés accumulées',p.social.scarcity)}${micro('Soutien accompagné',p.social.support?'Actif':'Aucun actuellement')}${micro('Condamnations dans cette vie',g.record)}${micro('Détention restante',g.sentence+' an(s)')}<button class="btn primary" onclick="act('seekSupport')">Chercher un accompagnement · 1</button><button class="btn" onclick="openHubJobs()">Chercher un revenu régulier</button><p class="hint">L’instabilité réduit l’énergie et certaines possibilités. Le soutien, l’emploi, la formation et les liens peuvent rouvrir des portes.</p></div><div class="card"><h3>${g.level?'Une place dans un réseau fictif':'Une voie à haut risque'}</h3>${micro('Position',g.level?['','Membre','Figure du réseau','Cadre','Direction du réseau'][g.level]:'Aucune')}${micro('Dépendance au réseau',Math.round(g.coercion)+'/100')}${micro('Exposition judiciaire',Math.round(g.heat)+'/100')}${micro('Années dans le réseau',g.years)}<p>Cette trajectoire peut apporter de l’argent, mais aussi de la dépendance, des blessures, une perte d’actifs et des années de détention. Elle ne dépend pas automatiquement de votre pays ou de votre origine.</p><div class="row">${g.level?'<button class="btn danger" onclick="act(\'gangRise\')">Accepter une place plus haute</button><button class="btn primary" onclick="act(\'gangExit\')">Tenter de quitter · D20</button>':'<button class="btn danger" onclick="confirmGangEntry()">Envisager cette trajectoire</button>'}<button class="btn" onclick="beginReintegration()">Un accompagnement durable</button></div></div></div><div class="notice">Les trajectoires criminelles sont fictives et racontées à un niveau abstrait. Les risques judiciaires ne sont pas des statistiques observées. Les condamnations restent personnelles : elles ne sont pas héritées par les enfants.</div>`}
function confirmGangEntry(){modal(`<h2>Entrer dans un réseau criminel ?</h2><p>Ce choix peut apporter un revenu immédiat, mais crée une dépendance au réseau. L’exposition à la violence et à la détention augmente avec le temps. Les revenus sont variables ; une condamnation peut confisquer des liquidités et interrompre votre parcours.</p><div class="row"><button class="btn primary" onclick="document.getElementById('modal').close();act('seekSupport')">Chercher un soutien régulier</button><button class="btn danger" onclick="document.getElementById('modal').close();act('gangJoin')">Choisir cette voie fictive</button></div>`)}
function beginReintegration(){const r=Life.startProject(state,'reintegration',{effort:Math.min(2,Life.available(state.person)),strategy:'safe'});if(r.ok){save();$('#modal').close();render()}toast(r.message)}
const priorHubJobs=openHubJobs;openHubJobs=function(){pauseClock();modal(`<h2>Les métiers qui s’ouvrent cette année.</h2><div class="grid">${Life.offers(state).map(offerCard).join('')||'<p>Aucune offre ne remplit vos conditions actuelles.</p>'}</div><div class="row"><button class="btn" onclick="occupationAtlas()">Explorer les 410 métiers</button><button class="btn" onclick="credentialSchool()">Préparer une qualification</button><button class="btn" onclick="act('prepare');openHubJobs()">Préparer les entretiens · 1</button></div>`);$('#modal').classList.add('wide-modal')};
const societyDiceBefore=diceForAction;diceForAction=function(type,value){if(type==='applyOccupation'){const j=Life.jobById(value);return j?Life.checkModel(state,'job',Life.makeOffer(state,j,true)):null}if(['careerImpact','residency','naturalize','gangExit'].includes(type))return Life.checkModel(state,type);return societyDiceBefore(type,value)};
const priorSocietyDecision=decide;decide=function(index){const e=state.pending,x=e?.choices[index],type=x?.fx.societyAction;if(type){const m=Life.checkModel(state,type);if(m){pauseClock();openDice({kind:'decision',index,eventId:e.id},m);return}}priorSocietyDecision(index)};
const priorYearHub=yearHub;yearHub=function(){let html=priorYearHub();const p=state.person;if(p.age>=18){const extra=[];if(p.outlaw.sentence)extra.push(`<div class="hub-card attention"><h4>Votre parcours est interrompu par la détention.</h4><p>${p.outlaw.sentence} an(s) restent dans cette histoire. Les apprentissages et la réinsertion peuvent préparer la suite.</p><button class="btn" onclick="beginReintegration()">Préparer la reconstruction</button></div>`);if(p.social.housing==='street'||p.outlaw.level)extra.push(`<div class="hub-card attention"><h4>Une stabilité à reconstruire</h4><p>${p.outlaw.level?'La dépendance au réseau grandit avec le temps. Une sortie peut se préparer.':'Le manque de logement stable pèse sur votre santé et l’accès aux autres possibilités.'}</p><button class="btn" onclick="act('seekSupport')">Chercher de l’aide · 1</button>${p.outlaw.level?'<button class="btn" onclick="act(\'gangExit\')">Tenter de quitter le réseau</button>':''}</div>`);if(p.occupationGoal){const j=Life.jobById(p.occupationGoal);extra.push(`<div class="hub-card"><h4>Votre cap : ${esc(j.title)}</h4><p>${esc(Life.jobReasons(state,j)[0]||'Les conditions d’entrée sont remplies. Une candidature reste à réussir.')}</p><button class="btn" onclick="occupationDetail('${j.id}')">Voir la prochaine étape</button></div>`)}else extra.push('<div class="hub-card"><h4>Quel métier aimeriez-vous explorer ?</h4><p>Usine, création, diplomatie, transports, recherche : 410 parcours et leurs conditions sont visibles.</p><button class="btn" onclick="occupationAtlas()">Trouver une aspiration</button></div>');if(p.politics.experience||p.politics.office)extra.push(`<div class="hub-card"><h4>${p.politics.office?esc(p.politics.office.title):'Votre parcours civique se construit'}</h4><p>${p.politics.experience.toFixed(1)} ans d’engagement · confiance ${Math.round(p.politics.trust)}/100 · notoriété ${Math.round(p.politics.profile)}/100.</p><button class="btn" onclick="publicLifeModal()">Préparer la suite ici</button></div>`);else extra.push('<div class="hub-card"><h4>Changer quelque chose autour de vous.</h4><p>Un engagement local peut rester une contribution ou devenir la première étape d’un parcours politique.</p><button class="btn" onclick="publicLifeModal()">Explorer la vie publique</button></div>');html+='<div class="hub-cards society-hub">'+extra.join('')+'</div>'}return html};
const originalFamilyView=familyView;familyView=function(){Life.ensure(state);const p=state.person;return originalFamilyView()+`<div class="grid" style="margin-top:20px"><div class="card"><h3>L’héritage des possibilités</h3>${micro('Capital éducatif transmis',Math.round(p.familyCapital.education)+'/100')}${micro('Réseau familial transmis',Math.round(p.familyCapital.network)+'/100')}${micro('Nom public dans la famille',Math.round(p.familyCapital.publicName)+'/100')}<p>Les enfants peuvent recevoir un cadre plus stable, des langues, des contacts, une éducation et du patrimoine. Ils ne reçoivent ni les diplômes ni les condamnations de leurs parents.</p></div><div class="card"><h3>Naître ailleurs change parfois ce qui devient possible.</h3>${citizenshipPanel()}<p>Une première génération peut stabiliser ses ressources et migrer. La suivante peut grandir dans un nouveau pays ; une autre peut bâtir les qualifications et les soutiens nécessaires à une fonction exceptionnelle. Rien n’impose que cette progression se fasse en quatre générations, ni qu’elle réussisse.</p></div></div>`};
const previousSources=sources;sources=function(){previousSources();const d=$('#modal');d.innerHTML+='<h3>Métiers et institutions</h3><p>410 métiers dans 41 domaines, inspirés des grands groupes ISCO-08 de l’OIT. Revenus, concurrence, qualifications et durées de formation sont des règles de simulation. Les parcours de séjour, de naturalisation et la plupart des institutions nationales sont simplifiés.</p><p>La présidence américaine conserve les conditions de citoyenneté américaine dès la naissance, d’âge minimum de 35 ans et de 14 années de résidence. Le modèle distingue la naturalisation d’une acquisition à la naissance, y compris certains enfants nés à l’étranger d’un parent américain ; il ne reproduit pas tous les cas de droit de la nationalité.</p><a href="https://ilostat.ilo.org/methods/concepts-and-definitions/classification-occupation/" target="_blank" rel="noopener">OIT · ISCO-08 ↗</a><a href="https://constitution.congress.gov/browse/essay/artII-S1-C5-1/ALDE_00013692/" target="_blank" rel="noopener">Constitution Annotated · présidence américaine ↗</a>';};
const previousWelcome=welcome;welcome=function(){previousWelcome();$('#app').innerHTML=$('#app').innerHTML.replace('197 pays · Des années qui défilent · Des générations qui continuent','197 pays · 410 métiers · Des trajectoires sur plusieurs générations')};
$('#modal').addEventListener('close',()=>$('#modal').classList.remove('wide-modal'));
if(state){Life.ensure(state);save()}render();
